export const WEB_JS = "// Shared appearance preferences; never stores credentials.\n(function(){\n  var root=document.documentElement;\n  function read(k){try{return localStorage.getItem(k)}catch(_){return null}}\n  function save(k,v){try{localStorage.setItem(k,v)}catch(_){}}\n  var explicitLanguage=new URLSearchParams(location.search).get('lang');\n  if(explicitLanguage==='zh'||explicitLanguage==='en')save('publy-lang-override-v2',explicitLanguage);\n  var language=explicitLanguage||read('publy-lang-override-v2');\n  if(language!=='zh'&&language!=='en')language=(navigator.language||'en').startsWith('zh')?'zh':'en';\n  function lang(v){root.lang=v==='zh'?'zh-CN':'en';document.querySelectorAll('[data-switch]').forEach(function(b){b.setAttribute('aria-pressed',String(b.dataset.switch===v))})}\n  if(document.querySelector('[data-switch]'))lang(language);\n  document.querySelectorAll('[data-switch]').forEach(function(b){b.addEventListener('click',function(){lang(b.dataset.switch);save('publy-lang-override-v2',b.dataset.switch);var u=new URL(location.href);u.searchParams.set('lang',b.dataset.switch);history.replaceState(null,'',u.pathname+u.search+u.hash)})});\n  var theme=read('publy-theme');if(theme==='dark'||theme==='light')root.dataset.theme=theme;\n  document.querySelectorAll('[data-theme-switch]').forEach(function(b){b.setAttribute('aria-pressed',String(root.dataset.theme?root.dataset.theme==='dark':matchMedia('(prefers-color-scheme:dark)').matches));b.addEventListener('click',function(){var dark=root.dataset.theme?root.dataset.theme==='dark':matchMedia('(prefers-color-scheme:dark)').matches;root.dataset.theme=dark?'light':'dark';save('publy-theme',root.dataset.theme);b.setAttribute('aria-pressed',String(!dark))})});\n})();\n";
export const FAMILY_CSS = "/* site-kit v1.0.4 — generated from github.com/turlamai/site-kit; do not edit per-site. */\n/* ============================================================\n   site-kit family.css — jrtx.site family design system\n   Single source of truth: github.com/turlamai/site-kit\n   Version stamp is prepended by sync.sh; do not edit per-site.\n   ============================================================ */\n\n/* ---------- Tokens ---------- */\n:root {\n    /* Family accent: one terracotta for the whole family. */\n    --kit-accent: #D97757;\n    --kit-accent-hover: #C25F3D;\n    --kit-accent-strong: #A94E31;\n    --kit-accent-soft: rgba(217, 119, 87, 0.12);\n    --kit-accent-soft-strong: rgba(217, 119, 87, 0.22);\n    --kit-on-accent: #FFFFFF;\n\n    /* Warm neutrals, light theme (html[data-theme=\"light\"] is the default). */\n    --kit-bg: #FAF8F5;\n    --kit-bg-elevated: #FFFFFF;\n    --kit-surface: #F3EFE9;\n    --kit-surface-2: #ECE6DD;\n    --kit-text: #201B16;\n    --kit-text-2: #5D554C;\n    --kit-text-3: #8A8177;\n    --kit-border: rgba(32, 27, 22, 0.12);\n    --kit-border-strong: rgba(32, 27, 22, 0.24);\n    --kit-shadow: 0 1px 2px rgba(32, 27, 22, 0.05), 0 8px 24px rgba(32, 27, 22, 0.07);\n    --kit-shadow-lift: 0 2px 4px rgba(32, 27, 22, 0.06), 0 16px 40px rgba(32, 27, 22, 0.12);\n\n    --kit-font-display: \"Newsreader\", \"Songti SC\", \"Noto Serif SC\", Georgia, serif;\n    --kit-font-sans: \"Inter\", -apple-system, BlinkMacSystemFont, \"Segoe UI\",\n        \"PingFang SC\", \"Hiragino Sans GB\", \"Microsoft YaHei\", \"Noto Sans CJK SC\", sans-serif;\n    --kit-font-mono: ui-monospace, \"SF Mono\", \"Cascadia Code\", \"JetBrains Mono\",\n        Consolas, \"Liberation Mono\", monospace;\n\n    --kit-radius-s: 8px;\n    --kit-radius-m: 12px;\n    --kit-radius-l: 16px;\n    --kit-nav-height: 60px;\n    --kit-content-width: 1080px;\n    --kit-prose-width: 720px;\n}\n\nhtml[data-theme=\"dark\"] {\n    --kit-accent: #E08A6B;\n    --kit-accent-hover: #E89E82;\n    --kit-accent-strong: #D97757;\n    --kit-accent-soft: rgba(224, 138, 107, 0.14);\n    --kit-accent-soft-strong: rgba(224, 138, 107, 0.26);\n    --kit-on-accent: #1D120C;\n\n    --kit-bg: #16120F;\n    --kit-bg-elevated: #1F1A16;\n    --kit-surface: #262019;\n    --kit-surface-2: #2E2721;\n    --kit-text: #F1ECE5;\n    --kit-text-2: #A89F93;\n    --kit-text-3: #7A7166;\n    --kit-border: rgba(241, 236, 229, 0.13);\n    --kit-border-strong: rgba(241, 236, 229, 0.26);\n    --kit-shadow: 0 1px 2px rgba(0, 0, 0, 0.4), 0 8px 24px rgba(0, 0, 0, 0.35);\n    --kit-shadow-lift: 0 2px 4px rgba(0, 0, 0, 0.4), 0 16px 40px rgba(0, 0, 0, 0.5);\n}\n\n/* ---------- Reset & base ---------- */\n*, *::before, *::after { box-sizing: border-box; }\n\n/* Component display declarations (kit-btn etc.) beat the UA [hidden] rule;\n   language blocks and other hidden content rely on this staying absolute. */\n[hidden] { display: none !important; }\n\nhtml {\n    -webkit-text-size-adjust: 100%;\n    scroll-behavior: smooth;\n    scroll-padding-top: calc(var(--kit-nav-height) + 16px);\n}\n\nbody {\n    margin: 0;\n    font-family: var(--kit-font-sans);\n    font-size: 16px;\n    line-height: 1.65;\n    color: var(--kit-text);\n    background: var(--kit-bg);\n    -webkit-font-smoothing: antialiased;\n    text-rendering: optimizeLegibility;\n}\n\n/* Family-wide link policy: never the browser-default blue underline.\n   Inline links inherit text color and gain an accent underline on hover;\n   navigation and button links are styled by their components. */\na {\n    color: inherit;\n    text-decoration: none;\n    transition: color 0.15s ease;\n}\na:hover { color: var(--kit-accent); }\n.prose a, .kit-rich a {\n    color: var(--kit-accent-strong);\n    text-decoration: underline;\n    text-decoration-color: var(--kit-accent-soft-strong);\n    text-underline-offset: 3px;\n    text-decoration-thickness: 1.5px;\n}\n.prose a:hover, .kit-rich a:hover { text-decoration-color: currentColor; }\n\nimg, svg, video { max-width: 100%; height: auto; display: block; }\n\nh1, h2, h3, h4 { margin: 0; font-weight: 600; line-height: 1.2; }\np { margin: 0; }\n\ncode, pre, kbd {\n    font-family: var(--kit-font-mono);\n    font-size: 0.92em;\n}\n\npre {\n    background: var(--kit-surface);\n    border: 1px solid var(--kit-border);\n    border-radius: var(--kit-radius-m);\n    padding: 16px 20px;\n    overflow-x: auto;\n    line-height: 1.55;\n}\npre code { background: none; padding: 0; font-size: 1em; }\ncode {\n    background: var(--kit-surface);\n    border-radius: 5px;\n    padding: 0.15em 0.4em;\n}\n\n::selection { background: var(--kit-accent-soft-strong); }\n\n:focus-visible {\n    outline: 2px solid var(--kit-accent);\n    outline-offset: 2px;\n    border-radius: 4px;\n}\n\n@media (prefers-reduced-motion: reduce) {\n    html { scroll-behavior: auto; }\n    *, *::before, *::after {\n        animation-duration: 0.01ms !important;\n        transition-duration: 0.01ms !important;\n    }\n}\n\n/* ---------- Layout primitives ---------- */\n.kit-container {\n    width: min(var(--kit-content-width), 100% - 48px);\n    margin-inline: auto;\n}\n\n.kit-section { padding: 96px 0; }\n.kit-section--tight { padding: 64px 0; }\n@media (max-width: 720px) {\n    .kit-section { padding: 64px 0; }\n    .kit-section--tight { padding: 48px 0; }\n}\n\n.kit-section--alt {\n    background: var(--kit-bg-elevated);\n    border-block: 1px solid var(--kit-border);\n}\n\n/* Section header: eyebrow + display title + lead */\n.kit-kicker {\n    display: block;\n    font-size: 12.5px;\n    font-weight: 600;\n    letter-spacing: 0.09em;\n    text-transform: uppercase;\n    color: var(--kit-accent-strong);\n    margin-bottom: 14px;\n}\nhtml[data-theme=\"dark\"] .kit-kicker { color: var(--kit-accent); }\n\n.kit-h2 {\n    font-family: var(--kit-font-display);\n    font-size: clamp(1.9rem, 3.6vw, 2.6rem);\n    font-weight: 500;\n    letter-spacing: -0.01em;\n    line-height: 1.15;\n    max-width: 22ch;\n}\n\n.kit-lead {\n    margin-top: 18px;\n    font-size: 17.5px;\n    line-height: 1.7;\n    color: var(--kit-text-2);\n    max-width: 56ch;\n}\n\n/* ---------- Navigation ---------- */\n.kit-nav {\n    position: sticky;\n    top: 0;\n    z-index: 50;\n    height: var(--kit-nav-height);\n    background: color-mix(in srgb, var(--kit-bg) 82%, transparent);\n    -webkit-backdrop-filter: saturate(1.4) blur(14px);\n    backdrop-filter: saturate(1.4) blur(14px);\n    border-bottom: 1px solid var(--kit-border);\n}\n.kit-nav-inner {\n    height: 100%;\n    display: flex;\n    align-items: center;\n    gap: 28px;\n}\n.kit-brand {\n    display: flex;\n    align-items: center;\n    gap: 10px;\n    font-weight: 650;\n    font-size: 16.5px;\n    letter-spacing: -0.01em;\n    color: var(--kit-text);\n}\n.kit-brand:hover { color: var(--kit-text); }\n.kit-brand-mark {\n    width: 24px;\n    height: 24px;\n    border-radius: 6px;\n    flex: none;\n}\n.kit-nav-links {\n    display: flex;\n    align-items: center;\n    gap: 22px;\n    margin-left: auto;\n}\n.kit-nav-links a {\n    font-size: 14px;\n    font-weight: 500;\n    color: var(--kit-text-2);\n}\n.kit-nav-links a:hover { color: var(--kit-text); }\n\n.kit-nav-actions {\n    display: flex;\n    align-items: center;\n    gap: 8px;\n    margin-left: 8px;\n    padding-left: 20px;\n    border-left: 1px solid var(--kit-border);\n}\n\n/* Nav links fold below 860px: the full desktop nav (brand + links + actions)\n   does not fit tablet widths, and 760px left a gap where wide navs overflowed. */\n@media (max-width: 860px) {\n    .kit-nav-links { display: none; }\n}\n@media (max-width: 760px) {\n    .kit-nav-actions { margin-left: auto; padding-left: 0; border-left: none; }\n}\n\n/* Icon buttons in nav (theme toggle, GitHub) */\n.kit-icon-btn {\n    display: inline-flex;\n    align-items: center;\n    justify-content: center;\n    width: 34px;\n    height: 34px;\n    border: 1px solid var(--kit-border);\n    border-radius: 9px;\n    background: transparent;\n    color: var(--kit-text-2);\n    cursor: pointer;\n    transition: color 0.15s ease, border-color 0.15s ease, background 0.15s ease;\n}\n.kit-icon-btn:hover {\n    color: var(--kit-text);\n    border-color: var(--kit-border-strong);\n    background: var(--kit-surface);\n}\n.kit-icon-btn svg { width: 17px; height: 17px; }\n\n/* ---------- Language dropdown ---------- */\n.kit-lang { position: relative; }\n.kit-lang-btn {\n    display: inline-flex;\n    align-items: center;\n    gap: 6px;\n    height: 34px;\n    padding: 0 12px;\n    border: 1px solid var(--kit-border);\n    border-radius: 9px;\n    background: transparent;\n    color: var(--kit-text-2);\n    font-family: inherit;\n    font-size: 13px;\n    font-weight: 500;\n    cursor: pointer;\n    transition: color 0.15s ease, border-color 0.15s ease, background 0.15s ease;\n}\n.kit-lang-btn:hover {\n    color: var(--kit-text);\n    border-color: var(--kit-border-strong);\n    background: var(--kit-surface);\n}\n.kit-lang-btn svg { width: 14px; height: 14px; opacity: 0.7; }\n\n.kit-lang-menu {\n    position: absolute;\n    top: calc(100% + 6px);\n    right: 0;\n    min-width: 140px;\n    margin: 0;\n    padding: 6px;\n    list-style: none;\n    background: var(--kit-bg-elevated);\n    border: 1px solid var(--kit-border);\n    border-radius: var(--kit-radius-m);\n    box-shadow: var(--kit-shadow-lift);\n    display: none;\n}\n.kit-lang.kit-open .kit-lang-menu { display: block; }\n.kit-lang-menu button {\n    display: flex;\n    align-items: center;\n    justify-content: space-between;\n    gap: 12px;\n    width: 100%;\n    padding: 8px 12px;\n    border: 0;\n    border-radius: 8px;\n    background: transparent;\n    color: var(--kit-text);\n    font-family: inherit;\n    font-size: 13.5px;\n    cursor: pointer;\n}\n.kit-lang-menu button:hover { background: var(--kit-surface); }\n.kit-lang-menu button[aria-current=\"true\"] { color: var(--kit-accent-strong); font-weight: 600; }\nhtml[data-theme=\"dark\"] .kit-lang-menu button[aria-current=\"true\"] { color: var(--kit-accent); }\n.kit-lang-menu button[aria-current=\"true\"]::after { content: \"✓\"; font-size: 12px; }\n\n/* ---------- Buttons ---------- */\n.kit-btn {\n    display: inline-flex;\n    align-items: center;\n    justify-content: center;\n    gap: 9px;\n    height: 46px;\n    padding: 0 22px;\n    border-radius: var(--kit-radius-m);\n    border: 1px solid transparent;\n    font-family: inherit;\n    font-size: 15px;\n    font-weight: 600;\n    letter-spacing: 0.01em;\n    cursor: pointer;\n    transition: background 0.15s ease, border-color 0.15s ease, color 0.15s ease,\n        transform 0.15s ease, box-shadow 0.15s ease;\n    white-space: nowrap;\n}\n.kit-btn svg { width: 17px; height: 17px; }\n\n.kit-btn--primary {\n    background: var(--kit-accent);\n    color: var(--kit-on-accent);\n    box-shadow: 0 1px 2px rgba(0, 0, 0, 0.12), inset 0 1px 0 rgba(255, 255, 255, 0.14);\n}\n.kit-btn--primary:hover {\n    background: var(--kit-accent-hover);\n    color: var(--kit-on-accent);\n    transform: translateY(-1px);\n    box-shadow: 0 4px 14px var(--kit-accent-soft-strong);\n}\n.kit-btn--primary:active { transform: translateY(0); }\n\n.kit-btn--secondary {\n    background: var(--kit-bg-elevated);\n    border-color: var(--kit-border-strong);\n    color: var(--kit-text);\n}\n.kit-btn--secondary:hover {\n    border-color: var(--kit-accent);\n    color: var(--kit-accent-strong);\n    transform: translateY(-1px);\n}\nhtml[data-theme=\"dark\"] .kit-btn--secondary:hover { color: var(--kit-accent); }\n\n.kit-btn--ghost {\n    background: transparent;\n    color: var(--kit-accent-strong);\n    padding: 0 10px;\n    height: 42px;\n}\nhtml[data-theme=\"dark\"] .kit-btn--ghost { color: var(--kit-accent); }\n.kit-btn--ghost:hover { color: var(--kit-accent-hover); }\n.kit-btn--ghost .kit-btn-arrow { transition: transform 0.15s ease; }\n.kit-btn--ghost:hover .kit-btn-arrow { transform: translateX(3px); }\n\n.kit-btn-row {\n    display: flex;\n    align-items: center;\n    flex-wrap: wrap;\n    gap: 14px;\n}\n\n/* ---------- Download split-button + platform menu ---------- */\n.kit-dl { position: relative; display: inline-flex; }\n.kit-dl .kit-btn--primary { border-top-right-radius: 0; border-bottom-right-radius: 0; }\n.kit-dl-caret {\n    display: inline-flex;\n    align-items: center;\n    justify-content: center;\n    width: 34px;\n    height: 46px;\n    margin-left: -1px;\n    border: 0;\n    border-radius: 0 var(--kit-radius-m) var(--kit-radius-m) 0;\n    background: var(--kit-accent);\n    color: var(--kit-on-accent);\n    cursor: pointer;\n    transition: background 0.15s ease;\n}\n.kit-dl-caret:hover { background: var(--kit-accent-hover); }\n.kit-dl-caret svg { width: 14px; height: 14px; }\n\n.kit-dl-menu {\n    position: absolute;\n    top: calc(100% + 8px);\n    left: 0;\n    min-width: 280px;\n    margin: 0;\n    padding: 6px;\n    list-style: none;\n    background: var(--kit-bg-elevated);\n    border: 1px solid var(--kit-border);\n    border-radius: var(--kit-radius-l);\n    box-shadow: var(--kit-shadow-lift);\n    display: none;\n    z-index: 40;\n}\n.kit-dl.kit-open .kit-dl-menu { display: block; }\n.kit-dl-menu a {\n    display: flex;\n    align-items: center;\n    gap: 12px;\n    padding: 10px 14px;\n    border-radius: 10px;\n    color: var(--kit-text);\n}\n.kit-dl-menu a:hover { background: var(--kit-surface); color: var(--kit-text); }\n.kit-dl-menu .kit-dl-os { font-weight: 600; font-size: 14px; flex: 1; }\n.kit-dl-menu .kit-dl-kind {\n    font-size: 11.5px;\n    color: var(--kit-text-3);\n    font-family: var(--kit-font-mono);\n}\n.kit-dl-menu .kit-dl-note {\n    padding: 8px 14px 6px;\n    font-size: 12px;\n    color: var(--kit-text-3);\n    border-top: 1px solid var(--kit-border);\n    margin-top: 6px;\n}\n\n/* ---------- Hero ---------- */\n.kit-hero {\n    padding: 108px 0 88px;\n    text-align: center;\n    position: relative;\n}\n@media (max-width: 720px) { .kit-hero { padding: 72px 0 56px; } }\n\n.kit-hero .kit-eyebrow {\n    display: inline-flex;\n    align-items: center;\n    gap: 8px;\n    font-size: 13px;\n    font-weight: 600;\n    letter-spacing: 0.05em;\n    color: var(--kit-accent-strong);\n    background: var(--kit-accent-soft);\n    border: 1px solid var(--kit-accent-soft-strong);\n    border-radius: 999px;\n    padding: 7px 16px;\n    margin-bottom: 28px;\n}\nhtml[data-theme=\"dark\"] .kit-hero .kit-eyebrow { color: var(--kit-accent); }\n\n.kit-hero h1 {\n    font-family: var(--kit-font-display);\n    font-size: clamp(2.7rem, 6.4vw, 4.4rem);\n    font-weight: 500;\n    letter-spacing: -0.015em;\n    line-height: 1.06;\n    margin-inline: auto;\n    max-width: 18ch;\n    text-wrap: balance;\n}\n\n.kit-hero .kit-lead {\n    margin: 24px auto 0;\n    font-size: 18.5px;\n    max-width: 58ch;\n    text-wrap: pretty;\n}\n\n.kit-hero .kit-btn-row { justify-content: center; margin-top: 36px; }\n\n.kit-hero .kit-hero-meta {\n    margin-top: 18px;\n    font-size: 13.5px;\n    color: var(--kit-text-3);\n}\n\n/* ---------- Feature grid & cards ---------- */\n.kit-grid {\n    display: grid;\n    grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));\n    gap: 18px;\n}\n/* Grid items shrink below their content's min width; wide code blocks\n   inside cards scroll instead of stretching the track. */\n.kit-grid > * { min-width: 0; }\n.kit-grid--3 { grid-template-columns: repeat(3, 1fr); }\n.kit-grid--2 { grid-template-columns: repeat(2, 1fr); }\n@media (max-width: 960px) {\n    .kit-grid--3, .kit-grid--2 { grid-template-columns: repeat(2, 1fr); }\n}\n@media (max-width: 640px) {\n    .kit-grid--3, .kit-grid--2 { grid-template-columns: 1fr; }\n}\n\n.kit-card {\n    background: var(--kit-bg-elevated);\n    border: 1px solid var(--kit-border);\n    border-radius: var(--kit-radius-l);\n    padding: 26px 26px 24px;\n    transition: box-shadow 0.2s ease, transform 0.2s ease, border-color 0.2s ease;\n}\n.kit-card:hover {\n    box-shadow: var(--kit-shadow);\n    transform: translateY(-2px);\n    border-color: var(--kit-border-strong);\n}\n.kit-card h3 {\n    font-size: 16.5px;\n    font-weight: 650;\n    letter-spacing: -0.01em;\n    margin-bottom: 8px;\n}\n.kit-card p {\n    font-size: 14.5px;\n    line-height: 1.6;\n    color: var(--kit-text-2);\n}\n.kit-card-icon {\n    display: inline-flex;\n    align-items: center;\n    justify-content: center;\n    width: 40px;\n    height: 40px;\n    border-radius: 11px;\n    background: var(--kit-accent-soft);\n    color: var(--kit-accent-strong);\n    margin-bottom: 16px;\n}\nhtml[data-theme=\"dark\"] .kit-card-icon { color: var(--kit-accent); }\n.kit-card-icon svg { width: 20px; height: 20px; }\n\n/* ---------- Platform chips ---------- */\n.kit-platforms {\n    display: flex;\n    flex-wrap: wrap;\n    gap: 12px;\n}\n.kit-platform-chip {\n    display: inline-flex;\n    align-items: center;\n    gap: 10px;\n    padding: 12px 20px;\n    border: 1px solid var(--kit-border);\n    border-radius: var(--kit-radius-m);\n    background: var(--kit-bg-elevated);\n    font-size: 14px;\n    font-weight: 600;\n}\n.kit-platform-chip svg { width: 18px; height: 18px; color: var(--kit-text-2); }\n.kit-platform-chip small {\n    font-weight: 500;\n    color: var(--kit-text-3);\n    font-size: 12px;\n}\n\n/* ---------- Steps ---------- */\n.kit-steps {\n    display: grid;\n    grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));\n    gap: 28px;\n    counter-reset: kit-step;\n}\n.kit-step { position: relative; }\n.kit-step::before {\n    counter-increment: kit-step;\n    content: counter(kit-step, decimal-leading-zero);\n    font-family: var(--kit-font-display);\n    font-size: 30px;\n    font-weight: 500;\n    color: var(--kit-accent);\n    opacity: 0.85;\n    display: block;\n    margin-bottom: 12px;\n}\n.kit-step h3 { font-size: 15.5px; font-weight: 650; margin-bottom: 6px; }\n.kit-step p { font-size: 14px; color: var(--kit-text-2); line-height: 1.6; }\n\n/* ---------- Footer ---------- */\n.kit-footer {\n    border-top: 1px solid var(--kit-border);\n    background: var(--kit-bg-elevated);\n    padding: 56px 0 40px;\n    font-size: 14px;\n}\n.kit-footer-grid {\n    display: grid;\n    grid-template-columns: 1.4fr 1fr 1fr 1fr;\n    gap: 40px;\n}\n@media (max-width: 820px) { .kit-footer-grid { grid-template-columns: 1fr 1fr; } }\n@media (max-width: 520px) { .kit-footer-grid { grid-template-columns: 1fr; } }\n\n.kit-footer .kit-brand { font-size: 15px; }\n.kit-footer-tagline {\n    margin-top: 12px;\n    color: var(--kit-text-2);\n    font-size: 13.5px;\n    line-height: 1.6;\n    max-width: 34ch;\n}\n.kit-footer h4 {\n    font-size: 12px;\n    font-weight: 600;\n    letter-spacing: 0.08em;\n    text-transform: uppercase;\n    color: var(--kit-text-3);\n    margin-bottom: 14px;\n}\n.kit-footer ul {\n    list-style: none;\n    margin: 0;\n    padding: 0;\n    display: grid;\n    gap: 9px;\n}\n.kit-footer a { color: var(--kit-text-2); font-size: 13.5px; }\n.kit-footer a:hover { color: var(--kit-accent); }\n.kit-footer-bottom {\n    margin-top: 44px;\n    padding-top: 22px;\n    border-top: 1px solid var(--kit-border);\n    display: flex;\n    flex-wrap: wrap;\n    gap: 16px;\n    align-items: center;\n    justify-content: space-between;\n    color: var(--kit-text-3);\n    font-size: 12.5px;\n}\n\n/* ---------- Prose (long-form / book pages) ---------- */\n.kit-prose {\n    max-width: var(--kit-prose-width);\n    margin-inline: auto;\n    font-size: 16.5px;\n}\n.kit-prose h1, .kit-prose h2, .kit-prose h3 {\n    font-family: var(--kit-font-display);\n    font-weight: 500;\n    letter-spacing: -0.01em;\n    margin: 1.8em 0 0.6em;\n}\n.kit-prose h1 { font-size: 2.2rem; }\n.kit-prose h2 { font-size: 1.7rem; }\n.kit-prose h3 { font-size: 1.3rem; }\n.kit-prose p, .kit-prose ul, .kit-prose ol { margin: 0 0 1em; color: var(--kit-text); }\n.kit-prose li { margin-bottom: 0.4em; }\n.kit-prose blockquote {\n    margin: 1.4em 0;\n    padding: 4px 20px;\n    border-left: 3px solid var(--kit-accent);\n    color: var(--kit-text-2);\n}\n\n/* ---------- Status badge (preview / license line) ---------- */\n.kit-badge {\n    display: inline-flex;\n    align-items: center;\n    gap: 7px;\n    font-size: 12.5px;\n    font-weight: 600;\n    letter-spacing: 0.02em;\n    padding: 5px 12px;\n    border-radius: 999px;\n    background: var(--kit-surface);\n    border: 1px solid var(--kit-border);\n    color: var(--kit-text-2);\n}\n.kit-badge::before {\n    content: \"\";\n    width: 6px;\n    height: 6px;\n    border-radius: 50%;\n    background: var(--kit-accent);\n}\n\n/* ---------- Utilities ---------- */\n.kit-text-2 { color: var(--kit-text-2); }\n.kit-text-3 { color: var(--kit-text-3); }\n.kit-mono { font-family: var(--kit-font-mono); }\n.kit-hidden { display: none !important; }\n\n/* Accent word inside a split display headline */\n.kit-accent-word { color: var(--kit-accent-strong); }\nhtml[data-theme=\"dark\"] .kit-accent-word { color: var(--kit-accent); }\n\n/* Tiny metadata chip (e.g. the framework layer a product is built on) */\n.kit-chip {\n    display: inline-block;\n    font-size: 11px;\n    font-weight: 600;\n    letter-spacing: 0.02em;\n    padding: 2.5px 9px;\n    border-radius: 999px;\n    background: var(--kit-surface-2);\n    color: var(--kit-text-2);\n}\n";
export const SETUP_TEMPLATE = "<!doctype html><html lang=\"en\" class=\"publy-web\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Connect WeChat · Publy</title><style>__WEB_CSS__</style><meta name=\"theme-color\" content=\"#D97757\"><link rel=\"icon\" type=\"image/svg+xml\" href=\"data:image/svg+xml,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20viewBox%3D%220%200%2064%2064%22%3E%3Crect%20width%3D%2264%22%20height%3D%2264%22%20rx%3D%2217%22%20fill%3D%22%23D97757%22%2F%3E%3Cpath%20d%3D%22M32%2048V18M20%2029l12-12%2012%2012%22%20fill%3D%22none%22%20stroke%3D%22white%22%20stroke-width%3D%225%22%20stroke-linecap%3D%22round%22%20stroke-linejoin%3D%22round%22%2F%3E%3C%2Fsvg%3E\"></head><body><main class=\"pw-wrap\"><nav class=\"pw-nav\" aria-label=\"Publy\"><a href=\"https://publy.jrtx.site/\">Publy</a><div class=\"pw-actions\"><a href=\"/hosted\"><span data-lang=\"en\">Account & access</span><span data-lang=\"zh\">账户与权益</span></a><button type=\"button\" class=\"secondary\" data-switch=\"en\">EN</button><button type=\"button\" class=\"secondary\" data-switch=\"zh\">中文</button><button type=\"button\" class=\"secondary\" data-theme-switch aria-pressed=\"false\"><span data-lang=\"en\">Light / dark</span><span data-lang=\"zh\">亮 / 暗</span></button></div></nav>\n<h1><span data-lang=\"en\">Connect your Official Account</span><span data-lang=\"zh\">连接你的公众号</span></h1><p class=\"pw-muted\"><span data-lang=\"en\">Three steps. Checking the connection never creates or publishes a draft.</span><span data-lang=\"zh\">分三步完成。检查连接不会创建草稿，也不会公开发布。</span></p>\n<div class=\"pw-warning\"><span data-lang=\"en\">Check your account’s official draft API permission before paying. A successful credential check alone does not prove draft permission. Hosted purchases are not generally open.</span><span data-lang=\"zh\">付款前先确认公众号具备官方草稿接口权限。凭据校验成功并不代表具有草稿接口权限。托管购买尚未全面开放。</span></div>\n<section class=\"pw-step\"><h2><span data-lang=\"en\">1 · Restore your Publy account</span><span data-lang=\"zh\">1 · 恢复 Publy 账户</span></h2><form id=\"restore\"><label for=\"api-key\">Publy API Key</label><input id=\"api-key\" type=\"password\" autocomplete=\"off\" required><p class=\"pw-muted\"><span data-lang=\"en\">Use the key saved when your account was created. This is not your WeChat AppSecret.</span><span data-lang=\"zh\">填写开户时保存的 Key，不是公众号的 AppSecret。</span></p><div class=\"pw-actions\"><button id=\"restore-button\" type=\"submit\"><span data-lang=\"en\">Check my account</span><span data-lang=\"zh\">查看我的账户</span></button><button type=\"button\" id=\"forget\" class=\"secondary\"><span data-lang=\"en\">Clear this tab</span><span data-lang=\"zh\">清除此标签页凭据</span></button></div></form><p id=\"session-state\" role=\"status\" class=\"pw-feedback\" aria-live=\"polite\"></p><p id=\"account-list\" class=\"pw-config\"></p></section>\n<section class=\"pw-step\"><h2><span data-lang=\"en\">2 · Add this service’s IP to WeChat</span><span data-lang=\"zh\">2 · 在微信中添加本服务的 IP</span></h2><p><span data-lang=\"en\">Server egress IP (not your computer’s IP):</span><span data-lang=\"zh\">服务器出口 IP（不是你电脑的 IP）：</span> <strong id=\"egress-ip\">__PUBLIC_IP__</strong></p><div class=\"pw-actions\"><button type=\"button\" id=\"copy-ip\" class=\"secondary\"><span data-lang=\"en\">Copy server IP</span><span data-lang=\"zh\">复制服务器 IP</span></button><a href=\"https://publy.jrtx.site/wechat.html\"><span data-lang=\"en\">Open the step-by-step guide →</span><span data-lang=\"zh\">打开逐步操作指南 →</span></a></div><p><span data-lang=\"en\">Open the official <a href=\"https://mp.weixin.qq.com/\" target=\"_blank\" rel=\"noopener noreferrer\">WeChat Official Accounts Platform</a> with an administrator’s account. Find the API IP whitelist in the developer settings; if redirected, use the official developer platform linked there. Add one IP on a new line and keep existing entries.</span><span data-lang=\"zh\">用管理员身份打开官方<a href=\"https://mp.weixin.qq.com/\" target=\"_blank\" rel=\"noopener noreferrer\">微信公众号平台</a>。在开发设置中找到 API IP 白名单；若后台提示迁移，请从其链接进入官方开发者平台。另起一行添加本页 IP，保留已有条目。</span></p><p class=\"pw-muted\"><span data-lang=\"en\">Do not change login security IPs, business domains or JS domains. Do not reset AppSecret just to follow this guide.</span><span data-lang=\"zh\">不要改登录安全 IP、业务域名或 JS 接口安全域名，也不要为了跟随教程重置 AppSecret。</span></p></section>\n<section class=\"pw-step card\"><h2><span data-lang=\"en\">3 · Check and connect</span><span data-lang=\"zh\">3 · 检查并连接</span></h2><form id=\"bind\"><label for=\"account-name\"><span data-lang=\"en\">Account nickname (shown in Obsidian)</span><span data-lang=\"zh\">公众号昵称（在 Obsidian 中显示）</span></label><input id=\"account-name\" maxlength=\"40\" required><label for=\"app-id\">WeChat AppID</label><input id=\"app-id\" autocomplete=\"off\" required><label for=\"app-secret\">WeChat AppSecret</label><input id=\"app-secret\" type=\"password\" autocomplete=\"off\" required><p class=\"pw-muted\"><span data-lang=\"en\">Connecting sends these WeChat credentials to this Publy server for validation and storage. Only use a server you trust. AppSecret is not saved in browser storage.</span><span data-lang=\"zh\">连接时，公众号凭据将发送至当前 Publy 服务器进行校验并保存。只在你信任的服务中操作；AppSecret 不写入浏览器存储。</span></p><button type=\"submit\" id=\"bind-button\" disabled><span data-lang=\"en\">Check and connect · no draft created</span><span data-lang=\"zh\">检查并连接 · 不创建草稿</span></button></form><p id=\"bind-state\" class=\"pw-feedback\" role=\"status\" aria-live=\"polite\"></p></section>\n<section class=\"pw-step\"><h2><span data-lang=\"en\">Next · Configure Obsidian</span><span data-lang=\"zh\">接下来 · 配置 Obsidian</span></h2><p><span data-lang=\"en\">Open Settings → Publy. Server address:</span><span data-lang=\"zh\">打开「设置 → Publy」。服务器地址：</span> <strong id=\"server-url\" class=\"pw-config\"></strong></p><p><span data-lang=\"en\">Paste your Publy API Key, select the connected account, then test the connection. Preview a non-sensitive note first. Draft submission always needs your explicit confirmation.</span><span data-lang=\"zh\">填入 Publy API Key，选择已连接的公众号，再测试连接。先预览一篇不含敏感信息的笔记；投递草稿需要你明确确认。</span></p><a href=\"https://publy.jrtx.site/wechat.html\"><span data-lang=\"en\">First draft, recovery and troubleshooting →</span><span data-lang=\"zh\">第一篇草稿、恢复与故障排查 →</span></a></section></main><script>__WEB_JS__</script><script>__SETUP_JS__</script></body></html>";
